param([string]$DataRoot='X:\XVoiceTraderData',[switch]$Json)
$ErrorActionPreference='Stop';$config=Join-Path $DataRoot 'state\local-edge-lab-v086-config.json';$reportFile=Join-Path $DataRoot 'state\local-edge-lab-v086-soak-report.json';$hoursFile=Join-Path $DataRoot 'state\local-edge-lab-v086-soak-hours.json';$taskName='VoiceTrader-LocalNode-SoakCertifier'
function ReadJson($p){if(Test-Path $p){try{return Get-Content -Raw $p|ConvertFrom-Json}catch{}};return $null}
$c=ReadJson $config;$r=ReadJson $reportFile;$hours=ReadJson $hoursFile;$t=Get-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue;$i=if($t){Get-ScheduledTaskInfo -TaskName $taskName -ErrorAction SilentlyContinue}else{$null};$out=[ordered]@{schemaVersion='voicetrader-local-edge-lab-v086-status-v1';generatedAt=(Get-Date).ToUniversalTime().ToString('o');configured=[bool]$c;task=[ordered]@{exists=[bool]$t;state=if($t){[string]$t.State}else{'MISSING'};lastRunTime=if($i -and $i.LastRunTime -gt [datetime]::MinValue){$i.LastRunTime.ToUniversalTime().ToString('o')}else{$null};lastTaskResult=if($i){[int64]$i.LastTaskResult}else{$null}};soakStatus=if($r){[string]$r.status}else{'NO_REPORT'};currentConsecutiveCertifiedHours=if($r){[int]$r.currentConsecutiveCertifiedHours}else{0};longestConsecutiveCertifiedHours=if($r){[int]$r.longestConsecutiveCertifiedHours}else{0};proofWindow=if($r){$r.proofWindow}else{$null};hoursStored=if($hours){@($hours).Count}else{0};governance=[ordered]@{readOnly=$true;blindResultsRead=$false;predictionInputAuthorized=$false;orderSubmission=$false;realMoneyRouting=$false}}
if($Json){$out|ConvertTo-Json -Depth 12;exit 0};Write-Host 'VoiceTrader v0.86 24h soak status';Write-Host "Task: $($out.task.state)";Write-Host "Status: $($out.soakStatus)";Write-Host "Current certified streak: $($out.currentConsecutiveCertifiedHours) / 24 hours";Write-Host "Longest certified streak: $($out.longestConsecutiveCertifiedHours) hours";if($out.proofWindow){Write-Host "PROVEN window: $($out.proofWindow.startHourMs) -> $($out.proofWindow.endHourMs)"};Write-Host 'Blind/results/profitability: NOT READ'
